import {
	Component, Inject, PLATFORM_ID, CUSTOM_ELEMENTS_SCHEMA, ChangeDetectorRef,
	ChangeDetectionStrategy
} from '@angular/core';
import { environment } from '../../../../environments/environment';
import { CommonModule } from '@angular/common';
import { TranslationService } from '../../../core/services/translation.service';
import { ClientsService } from '../../../providers/clients/clients.service';
@Component({
	selector: 'app-client-slider',
	standalone: true,
	imports: [CommonModule],
	templateUrl: './client-slider.component.html',
	styleUrl: './client-slider.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
	schemas: [CUSTOM_ELEMENTS_SCHEMA]
})
export class ClientSliderComponent {
	baseUrl: any;
	imagepath: any;
	clientData: any = [];
	filteredClients: any = [];
	constructor(
		@Inject(PLATFORM_ID) private platformId: Object,
		public translationService: TranslationService,
		private clientsService: ClientsService,
		private cdr: ChangeDetectorRef
	) {
		this.baseUrl = environment.url;
		this.imagepath = environment.baseUrl + '/public/';
		}

	ngOnInit(): void {
		this.getallClients();
	}
	getallClients() {
  this.clientsService.getClients({}).subscribe({
    next: (response: any) => {
      const clients = response.body.result;
      this.clientData = clients.map((item: any, index: number) => ({
        id: item._id || index,
        src: `${this.imagepath}/logo/${item.media_image_data.src}`,
        alt: item.media_image_data.alt,
        title: item.media_image_data.name,
      }));
      this.filteredClients = this.clientData.slice(0, 15);
      this.cdr.detectChanges();
    },
    error: (err) => console.log(err)
  });
}

}
