import { ChangeDetectionStrategy, ChangeDetectorRef, Component, CUSTOM_ELEMENTS_SCHEMA, Input, OnInit } from '@angular/core';
import { LucideAngularModule } from 'lucide-angular';
import { environment } from '../../../environments/environment';
import { CommonModule } from '@angular/common';
import { ProjectService } from '../../providers/project/project.service';
import { SwiperOptions } from 'swiper/types';
import { TranslateModule } from '@ngx-translate/core';
import { TranslationService } from '../../core/services/translation.service';
import { Router } from '@angular/router';

@Component({
	selector: 'app-works',
	standalone: true,
	imports: [CommonModule, LucideAngularModule, TranslateModule],
	templateUrl: './works.component.html',
	styleUrl: './works.component.scss',
	changeDetection: ChangeDetectionStrategy.OnPush,
	schemas: [CUSTOM_ELEMENTS_SCHEMA]
})
export class WorksComponent implements OnInit {

	// ✅ Pass the service name from the parent page
	@Input() serviceName: string = 'Branding';

	// ✅ Optional: customize the consultation link per page
	@Input() consultationLink: string = '';

	baseUrl: any;
	imagePath: any;
	currentPage: number = 1;
	allprojects: any = [];
	currentLimit: number = 100;

	recentoptions: SwiperOptions = {
		loop: true,
		speed: 700,
		spaceBetween: 14,
		autoplay: {
			delay: 3500,
			disableOnInteraction: false,
		},
		breakpoints: {
			0: { slidesPerView: 1 },
			480: { slidesPerView: 1 },
			740: { slidesPerView: 3 },
			940: { slidesPerView: 4 },
		},
	};

	constructor(
		private projectservice: ProjectService,
		private router: Router,
		private cdr: ChangeDetectorRef,
		public translationService: TranslationService
	) {
		this.imagePath = environment.baseUrl + '/public/';
		this.baseUrl = environment.url;
	}

	ngOnInit(): void {
		import('swiper/element/bundle').then((m) => m.register());
		if (!this.consultationLink) {
			this.consultationLink = `/contact/${this.serviceName}`;
		}
		this.get_AllProjects();
	}
bookConsultation() {
		this.router.navigate([this.translationService.localizedPath(this.consultationLink)], {
			state: {
				service: this.serviceName.toLowerCase(),
			},
		});
	}
	get_AllProjects() {
		const obj = {
			limit: this.currentLimit,
			page: this.currentPage,
		};

		this.projectservice.getAllProjects(obj).subscribe((response) => {
			if (response.code === 200) {
				const result = response.result ?? response.data ?? [];
				this.allprojects = result.filter((project: any) =>
					Array.isArray(project.dos_name) &&
					project.dos_name.some((name: string) =>
						name.toLowerCase() === this.serviceName.toLowerCase()
					) &&
					project.featured === true
				).slice(0, 4);
				this.cdr.markForCheck();
			}
		});
	}
}
