	getPackages() {
		this.paymentservice.getFilterPackages({})
			.subscribe((res: any) => {
				if (res?.body?.code === 200) {
					const packages: any[] = res.body.result || [];

					const filtered = packages
						.filter((pkg: any) =>
							pkg.packagecategory_name?.toLowerCase() === this.category?.toLowerCase()
						)
						.map((pkg: any) => ({
							...pkg,
							pricing: {
								AED: pkg.amount,
								USD: pkg.amount_usd
							}
						}));

					const sortedBySequence = [...filtered].sort(
						(a: any, b: any) => (a.sequence || 0) - (b.sequence || 0)
					);

					const featured = sortedBySequence.find((pkg: any) => pkg.isFeatured);
					const others = sortedBySequence.filter((pkg: any) => !pkg.isFeatured);

					if (featured) {
						this.packageData = [others[0], featured, others[1]].filter(Boolean);
					} else {
						this.packageData = [...sortedBySequence];
					}

					this.selectPackage(featured || this.packageData[0]);

					// ✅ IMPORTANT FIX
					this.cdr.detectChanges(); // or markForCheck()
				}
			});
	}
