	public hasEmailError = (form: string, errorName: string) => {
		const isArabic = this.translationService.currentLang() === 'ar';

		const emailRequired = isArabic
			? 'البريد الإلكتروني مطلوب.'
			: 'Email is required';

		const invalidEmail = isArabic
			? 'يرجى إدخال بريد إلكتروني صحيح.'
			: 'Invalid Email';

		if (form === 'referrer_email') {
			if (this.referralForm.controls['referrer_email'].value === '') {
				return emailRequired;
			} else if (this.referralForm.controls['referrer_email'].status === 'INVALID') {
				return invalidEmail;
			}
			return this.referralForm.controls['referrer_email'].hasError(errorName);
		}

		if (form === 'referred_email') {
			if (this.referralForm.controls['referred_email'].value === '') {
				return emailRequired;
			} else if (this.referralForm.controls['referred_email'].status === 'INVALID') {
				return invalidEmail;
			}
			return this.referralForm.controls['referred_email'].hasError(errorName);
		}

		if (this.paymentForm.controls['email'].value === '') {
			return emailRequired;
		} else if (this.paymentForm.controls['email'].status === 'INVALID') {
			return invalidEmail;
		}

		return this.paymentForm.controls['email'].hasError(errorName);
	};
	public hasReferralError = (controlName: string, errorName: string) => {
		return this.referralForm.controls[controlName].hasError(errorName);
	};

	public hasPhoneNumberError = (type: string, _errorName: string): string | boolean => {
		if (type === 'referrer.phone') {
			const ctrl = this.referralForm.get('referrer.phone');
			if (!ctrl?.value) return this.translationService.currentLang() === 'ar' ? 'الرقم مطلوب' : 'Phone Number is required';
			if (ctrl.status === 'INVALID') return this.translationService.currentLang() === 'ar' ? 'رقم الهاتف غير صحيح' : 'Invalid Phone Number';
			return false;
		} else if (type === 'referred.phone') {
			const ctrl = this.referralForm.get('referred.phone');
			if (!ctrl?.value) return this.translationService.currentLang() === 'ar' ? 'الرقم مطلوب' : 'Phone Number is required';
			if (ctrl.status === 'INVALID') return this.translationService.currentLang() === 'ar' ? 'رقم الهاتف غير صحيح' : 'Invalid Phone Number';
			return false;
		} else {
			// payment form
			const ctrl = this.paymentForm.get('contact');
			if (ctrl?.status === 'INVALID') return this.translationService.currentLang() === 'ar' ? 'الرقم مطلوب' : 'Phone Number is required';
			return false;
		}
	};
